<?php require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/layout.php';$q=db()->prepare('SELECT * FROM albums WHERE slug=?');$q->execute([$_GET['slug']??'']);$a=$q->fetch();if(!$a){http_response_code(404);require_once __DIR__.'/includes/not-found.php';render_image_not_found();}$q=db()->prepare('SELECT i.* FROM images i JOIN album_images ai ON ai.image_id=i.id WHERE ai.album_id=? AND i.status="ready" ORDER BY i.created_at DESC');$q->execute([$a['id']]);$items=$q->fetchAll();$albumDescription=t('seo_album_description',['count'=>count($items),'name'=>$a['title']]);$albumUrl=seo_language_url(current_language(),'/a/'.$a['slug']);$albumSchema=['@context'=>'https://schema.org','@type'=>'CollectionPage','name'=>$a['title'],'description'=>$albumDescription,'url'=>$albumUrl,'inLanguage'=>current_language(),'hasPart'=>array_map(fn($item)=>['@type'=>'ImageObject','name'=>$item['original_filename'],'url'=>base_url($item['short_id']),'contentUrl'=>base_url($item['short_id'].'.'.$item['extension'])],array_slice($items,0,50))];page_start($a['title'],$albumDescription,['index'=>$a['visibility']==='public','canonical_path'=>'/a/'.$a['slug'],'schema'=>$albumSchema]);?><main class="album-public"><section class="album-public-head"><div><p class="eyebrow"><?=e(strtoupper(t($a['visibility'])))?> · <?=e(strtoupper(t('albums')))?></p><h1><?=e($a['title'])?></h1><p><?=count($items)?> <?=e(t('images'))?> · IMGTR</p></div><button class="button button-secondary" type="button" id="copyAlbum"><?=e(t('share_album'))?></button></section><?php if(!$items):?><div class="empty"><p><?=e(t('empty_album'))?></p></div><?php else:?><div class="album-public-grid"><?php foreach($items as $i):?><article><a href="/<?=e($i['short_id'])?>"><img src="/<?=e($i['short_id'])?>.<?=e($i['extension'])?>" alt="<?=e($i['original_filename'])?>" loading="lazy"></a><div><b><?=e($i['original_filename'])?></b><small><?=e(format_bytes((int)$i['size']))?> · <?=number_format((int)$i['views'])?> <?=e(t('views'))?></small></div></article><?php endforeach?></div><?php endif?></main><script>document.getElementById('copyAlbum')?.addEventListener('click',async()=>{await navigator.clipboard.writeText(location.href);toast(<?=json_encode(t('copied'),JSON_UNESCAPED_UNICODE)?>)});</script><?php page_end();
